<?php
declare(strict_types=1);
if (!is_file(__DIR__.'/config.php')) { header('Location: install.php'); exit; }
require __DIR__.'/bootstrap.php';

if (isset($_GET['logout'])) { session_regenerate_id(true); $_SESSION=[]; header('Location: admin.php'); exit; }
$loginError='';
if (!admin_user() && $_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['login'])) {
    verify_csrf();
    $attempts=(int)($_SESSION['login_attempts']??0);$last=(int)($_SESSION['login_last']??0);
    if($attempts>=8 && time()-$last<900){$loginError='Too many attempts. Try again in 15 minutes.';}else{
        $stmt=db()->prepare('SELECT id,name,email,password_hash,role FROM admins WHERE email=? LIMIT 1');$stmt->execute([strtolower(trim((string)$_POST['email']))]);$user=$stmt->fetch();
        if($user&&password_verify((string)$_POST['password'],$user['password_hash'])){unset($user['password_hash']);$_SESSION['admin']=$user;$_SESSION['login_attempts']=0;session_regenerate_id(true);db()->prepare('UPDATE admins SET last_login_at=NOW() WHERE id=?')->execute([$user['id']]);header('Location: admin.php');exit;}
        $_SESSION['login_attempts']=$attempts+1;$_SESSION['login_last']=time();$loginError='Incorrect email or password.';
    }
}
if (!admin_user()) { ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SLIID Admin Login</title><style>
