function go(string $section,string $message='Saved'):never{header('Location: admin.php?section='.$section.'&notice='.urlencode($message));exit;}
function is_super():bool{return (admin_user()['role']??'')==='super_admin';}

if($_SERVER['REQUEST_METHOD']==='POST'&&!isset($_POST['login'])){
    require_admin();verify_csrf();$action=$_POST['action']??'';
    try{
        if($action==='save_member'){
            $id=(int)($_POST['id']??0);$image=upload_file('image',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'],'images');$values=[trim($_POST['name']),trim($_POST['membership_number']),$_POST['category'],trim($_POST['email']),trim($_POST['phone']),trim($_POST['location']),trim($_POST['specialisations']),trim($_POST['bio']),trim($_POST['website']),isset($_POST['featured'])?1:0,$_POST['status']];
            if($id){$sql='UPDATE members SET name=?,membership_number=?,category=?,email=?,phone=?,location=?,specialisations=?,bio=?,website=?,featured=?,status=?'.($image?',image_path=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','member',$id);}else{$values[]=$image;$stmt=db()->prepare('INSERT INTO members(name,membership_number,category,email,phone,location,specialisations,bio,website,featured,status,image_path) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute($values);$id=(int)db()->lastInsertId();audit('create','member',$id);}go('members','Member saved.');
        }
        if($action==='save_news'){
            $id=(int)($_POST['id']??0);$image=upload_file('image',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'],'images');$slug=slugify($_POST['slug']?:$_POST['title']);$published=$_POST['status']==='published'?($_POST['published_at']?:date('Y-m-d H:i:s')):null;$values=[trim($_POST['title']),$slug,trim($_POST['excerpt']),trim($_POST['content']),trim($_POST['category']),$_POST['status'],$published];
            if($id){$sql='UPDATE news SET title=?,slug=?,excerpt=?,content=?,category=?,status=?,published_at=?'.($image?',image_path=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','news',$id);}else{$values[]=$image;db()->prepare('INSERT INTO news(title,slug,excerpt,content,category,status,published_at,image_path) VALUES(?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();audit('create','news',$id);}go('news','News item saved.');
        }
        if($action==='save_event'){
            $id=(int)($_POST['id']??0);$image=upload_file('image',['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'],'images');$slug=slugify($_POST['slug']?:$_POST['title']);$values=[trim($_POST['title']),$slug,trim($_POST['summary']),trim($_POST['description']),trim($_POST['venue']),str_replace('T',' ',$_POST['starts_at']),$_POST['ends_at']?str_replace('T',' ',$_POST['ends_at']):null,trim($_POST['registration_url']),isset($_POST['featured'])?1:0,$_POST['status']];
            if($id){$sql='UPDATE events SET title=?,slug=?,summary=?,description=?,venue=?,starts_at=?,ends_at=?,registration_url=?,featured=?,status=?'.($image?',image_path=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','event',$id);}else{$values[]=$image;db()->prepare('INSERT INTO events(title,slug,summary,description,venue,starts_at,ends_at,registration_url,featured,status,image_path) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();audit('create','event',$id);}go('events','Event saved.');
        }
        if($action==='save_publication'){
            $id=(int)($_POST['id']??0);$file=upload_file('file',['application/pdf'=>'pdf'],'documents');$published=$_POST['status']==='published'?($_POST['published_at']?:date('Y-m-d H:i:s')):null;$values=[trim($_POST['title']),trim($_POST['description']),trim($_POST['category']),trim($_POST['external_url']),$_POST['status'],$published];
            if($id){$sql='UPDATE publications SET title=?,description=?,category=?,external_url=?,status=?,published_at=?'.($file?',file_path=?':'').' WHERE id=?';if($file)$values[]=$file;$values[]=$id;db()->prepare($sql)->execute($values);audit('update','publication',$id);}else{$values[]=$file;db()->prepare('INSERT INTO publications(title,description,category,external_url,status,published_at,file_path) VALUES(?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();audit('create','publication',$id);}go('publications','Publication saved.');
        }
        if($action==='set_status'){$table=$_POST['table']==='enquiries'?'enquiries':'membership_applications';$id=(int)$_POST['id'];$valid=$table==='enquiries'?['new','in_progress','resolved','spam']:['new','reviewing','approved','rejected'];$status=in_array($_POST['status'],$valid,true)?$_POST['status']:$valid[0];db()->prepare("UPDATE $table SET status=? WHERE id=?")->execute([$status,$id]);audit('status',$table,$id,['status'=>$status]);go($table==='enquiries'?'enquiries':'applications','Status updated.');}
        if($action==='delete'&&is_super()){$tables=['members'=>'member','news'=>'news','events'=>'event','publications'=>'publication'];$table=$_POST['table']??'';if(!isset($tables[$table]))throw new RuntimeException('Invalid item.');$id=(int)$_POST['id'];db()->prepare("DELETE FROM $table WHERE id=?")->execute([$id]);audit('delete',$tables[$table],$id);go($table,'Item deleted.');}
        if($action==='save_admin'&&is_super()){$email=strtolower(trim($_POST['email']));if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($_POST['password'])<12)throw new RuntimeException('Enter a valid email and a password of at least 12 characters.');db()->prepare('INSERT INTO admins(name,email,password_hash,role) VALUES(?,?,?,?)')->execute([trim($_POST['name']),$email,password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']==='super_admin'?'super_admin':'editor']);audit('create','admin',(int)db()->lastInsertId());go('admins','Administrator created.');}
    }catch(Throwable $e){$error=$e->getMessage();}
}
