function rows(string $table,string $order='id DESC'):array{return db()->query("SELECT * FROM $table ORDER BY $order LIMIT 250")->fetchAll();}
function record(string $table,int $id):array{if(!$id)return[];$stmt=db()->prepare("SELECT * FROM $table WHERE id=?");$stmt->execute([$id]);return$stmt->fetch()?:[];}
