function render_table(string $table,array $records,array $columns):string{ob_start();?><section class="panel list"><h2>Current records</h2><div class="table-wrap"><table><thead><tr><?php foreach($columns as $label):?><th><?=e($label)?></th><?php endforeach?><th>Actions</th></tr></thead><tbody><?php foreach($records as $r):?><tr><?php foreach($columns as $key=>$label):?><td><?=e((string)($r[$key]??''))?></td><?php endforeach?><td class="actions"><a href="?section=<?=$table?>&edit=<?=$r['id']?>">Edit</a><?php if(is_super()):?><form method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div></section><?php return ob_get_clean();}
function render_status_table(string $table,array $records,array $columns,array $statuses):string{ob_start();?><section class="panel list"><h2><?=e(ucwords(str_replace('_',' ',$table)))?></h2><div class="table-wrap"><table><thead><tr><?php foreach($columns as $label):?><th><?=e($label)?></th><?php endforeach?><th>Status</th></tr></thead><tbody><?php foreach($records as $r):?><tr><?php foreach($columns as $key=>$label):?><td><?=e((string)($r[$key]??''))?></td><?php endforeach?><td><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="set_status"><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach($statuses as $s):?><option <?=$s===$r['status']?'selected':''?>><?=$s?></option><?php endforeach?></select></form></td></tr><?php endforeach?></tbody></table></div></section><?php return ob_get_clean();}
